<script setup lang="ts">import{ref}from'vue';import type{Session}from '@remote/shared';defineProps<{session:Session;selected:boolean}>();defineEmits<{select:[];pin:[];archive:[];rename:[]}>();const menu=ref(false);const time=(v:string)=>new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric'}).format(new Date(v));</script>
<template><div class="session-item-wrap"><button class="session-item" :class="{selected}" @click="$emit('select')"><span class="session-copy"><strong>{{session.title}}</strong><em>{{time(session.updated_at)}}</em></span></button><button class="session-more" title="会话操作" @click="menu=!menu">•••</button><div v-if="menu" class="session-menu"><button @click="$emit('rename');menu=false">重命名</button><button @click="$emit('pin');menu=false">{{session.pinned?'取消置顶':'置顶'}}</button><button @click="$emit('archive');menu=false">{{session.status==='archived'?'取消归档':'归档'}}</button></div></div></template>
